func vtNl(b []byte, i int32) int32 {
	var k int32 = i
	for (k < port.BlobLen(b)) && (port.BlobU8(b, k) != 10) {
		k += 1
	}
	return k
}

func vtTab(b []byte, i int32, lim int32) int32 {
	// Index of the next tab in [i, lim), or lim.
	var k int32 = i
	for (k < lim) && (port.BlobU8(b, k) != 9) {
		k += 1
	}
	return k
}

func vtDec(b []byte, from int32, to int32) int32 {
	// A decimal, possibly negative.
	var k int32 = from
	var v int32 = 0
	var neg int32 = 0
	if (k < to) && (port.BlobU8(b, k) == 45) {
		neg = 1
		k += 1
	}
	for k < to {
		v = (v * 10) + (port.BlobU8(b, k) - 48)
		k += 1
	}
	if neg == 1 {
		return 0 - v
	}
	return v
}

func vtHexval(c int32) int32 {
	if (c >= 48) && (c <= 57) {
		return c - 48
	}
	if (c >= 97) && (c <= 102) {
		return c - 87
	}
	if (c >= 65) && (c <= 70) {
		return c - 55
	}
	return -1
}

func vtRgb(b []byte, from int32, to int32) int32 {
	// rrggbb as a number, or -1 for the field `-1`.
	var k int32 = from
	var v int32 = 0
	if (to - from) == 2 {
		return -1
	}
	for k < to {
		v = (v * 16) + vtHexval(port.BlobU8(b, k))
		k += 1
	}
	return v
}

func vtChan(v int32, i int32) int32 {
	// Channel i (0 blue, 1 green, 2 red) of a 0xRRGGBB colour.
	var w int32 = v
	var k int32 = 0
	for k < i {
		w = w / 256
		k += 1
	}
	return w % 256
}

func vtNear(got int32, want int32) int32 {
	// 1 when two colours are within two levels in every channel (-1 is only near -1).
	if (got < 0) || (want < 0) {
		if (got < 0) && (want < 0) {
			return 1
		}
		return 0
	}
	var i int32 = 0
	var d int32 = 0
	for i < 3 {
		d = vtChan(got, i) - vtChan(want, i)
		if (d > 2) || (d < -2) {
			return 0
		}
		i += 1
	}
	return 1
}

func vtRun(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, cx *port.Cells, ox *port.Cells, cs *port.Cells, out *port.Cells, f0 *port.Cells, f1 *port.Cells, f2 *port.Cells, f3 *port.Cells, gl *port.Cells, et *port.Cells, mk *port.Cells, fnt *port.Cells, pg *port.Cells, wd *port.Cells, ln *port.Cells, pa *port.Cells, im *port.Cells, pts *port.Cells, gx *port.Cells) int32 {
	port.CellsDrop(gl, 0)
	port.CellsDrop(et, 0)
	port.CellsDrop(mk, 0)
	port.CellsDrop(fnt, 0)
	port.CellsDrop(wd, 0)
	port.CellsDrop(ln, 0)
	port.CellsDrop(pa, 0)
	port.CellsDrop(im, 0)
	port.CellsDrop(pts, 0)
	var o int32 = pdfdoc.PdOpen(src, ar, dc, a, b, st)
	if o != 0 {
		return 100 + o
	}
	return pdfcontent.PcDocument(src, ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx)
}

func vtGlyphs(emonT *testing.T, gl *port.Cells, wd *port.Cells, mk *port.Cells, g int32, n int32, vis int32, by int32, src int32, wantRgb int32, cls int32, colour int32, line int32) int32 {
	// Check n glyphs from g: `vis`, `vby`, the word's source, and for a colour row the fill and class.
	var k int32 = 0
	var w int32 = 0
	var got int32 = 0
	port.AssertThatAt(emonT, (g+n) <= evidence.GlCount(gl), "there are glyphs for the row", line)
	if (g + n) > evidence.GlCount(gl) {
		return 0
	}
	for k < n {
		port.AssertEqAt(emonT, evidence.GlGet(gl, g+k, evidence.GfVis()), vis, "vis", line)
		port.AssertEqAt(emonT, evidence.GlGet(gl, g+k, evidence.GfVby()), by, "vby", line)
		w = evidence.GlGet(gl, g+k, evidence.ChWord())
		if w >= 0 {
			port.AssertEqAt(emonT, evidence.WdGet(wd, w, evidence.WfSrc()), src, "the word's source", line)
		}
		if colour == 1 {
			port.AssertThatAt(emonT, vtNear(evidence.GlGet(gl, g+k, evidence.GfFill()), wantRgb) == 1, "fill colour", line)
			got = evidence.GlGet(gl, g+k, evidence.GfCs())
			if got < 0 {
				got = 0
			}
			port.AssertEqAt(emonT, got, cls, "colour-space class", line)
		}
		k += 1
	}
	return 0
}

func vtOcg(emonT *testing.T, gl *port.Cells, mk *port.Cells, g int32, n int32, want int32, line int32) int32 {
	// The glyphs [g, g+n) are in an optional-content span whose default state is `want`.
	var k int32 = 0
	var m int32 = 0
	for k < n {
		m = evidence.MkOcgOf(mk, evidence.GlGet(gl, g+k, evidence.GfMark()))
		port.AssertThatAt(emonT, m >= 0, "an optional-content span encloses the glyph", line)
		if m >= 0 {
			port.AssertEqAt(emonT, evidence.MkGet(mk, m, evidence.MkfOcgdef()), want, "the span's default state", line)
		}
		k += 1
	}
	return 0
}

func vtWords(emonT *testing.T, gl *port.Cells, wd *port.Cells, line int32) int32 {
	// No word mixes visibilities: every glyph of a word has its first glyph's `vis` (and hidden-ness is the same, by
	// the source of the word).
	var w int32 = 0
	var k int32 = 0
	var g0 int32 = 0
	var n int32 = 0
	for w < evidence.WdCount(wd) {
		g0 = evidence.WdGet(wd, w, evidence.WfGfirst())
		n = evidence.WdGet(wd, w, evidence.WfGcount())
		k = 1
		for k < n {
			port.AssertEqAt(emonT, evidence.GlGet(gl, g0+k, evidence.GfVis()), evidence.GlGet(gl, g0, evidence.GfVis()), "a word has one visibility", line)
			k += 1
		}
		w += 1
	}
	return 0
}

func vtRows(emonT *testing.T, rows []byte) int32 {
	// Check the row file; answers how many rows were checked.
	var ar *port.Cells = port.NewCells()
	var dc *port.Cells = port.NewCells()
	var a *port.Cells = port.NewCells()
	var b *port.Cells = port.NewCells()
	var st *port.Cells = port.NewCells()
	var cx *port.Cells = port.NewCells()
	var ox *port.Cells = port.NewCells()
	var cs *port.Cells = port.NewCells()
	var out *port.Cells = port.NewCells()
	var f0 *port.Cells = port.NewCells()
	var f1 *port.Cells = port.NewCells()
	var f2 *port.Cells = port.NewCells()
	var f3 *port.Cells = port.NewCells()
	var gl *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var mk *port.Cells = port.NewCells()
	var fnt *port.Cells = port.NewCells()
	var pg *port.Cells = port.NewCells()
	var wd *port.Cells = port.NewCells()
	var ln *port.Cells = port.NewCells()
	var pa *port.Cells = port.NewCells()
	var im *port.Cells = port.NewCells()
	var pts *port.Cells = port.NewCells()
	var gx *port.Cells = port.NewCells()
	var epages *port.Cells = port.NewCells()
	var views *port.Cells = port.NewCells()
	var refs *port.Cells = port.NewCells()
	var feats *port.Cells = port.NewCells()
	var oruns *port.Cells = port.NewCells()
	var oblocks *port.Cells = port.NewCells()
	var olines *port.Cells = port.NewCells()
	var owords *port.Cells = port.NewCells()
	var osyms *port.Cells = port.NewCells()
	var oalts *port.Cells = port.NewCells()
	var inks *port.Cells = port.NewCells()
	var components *port.Cells = port.NewCells()
	var rules *port.Cells = port.NewCells()
	var prims *port.Cells = port.NewCells()
	var tlines *port.Cells = port.NewCells()
	var n int32 = port.BlobLen(rows)
	var pos int32 = 0
	var line int32 = 0
	var e int32 = 0
	var kind int32 = 0
	var checked int32 = 0
	var g int32 = 0
	var gprev int32 = 0
	var nprev int32 = 0
	var ii int32 = 0
	var status int32 = 0
	var p int32 = 0
	var q int32 = 0
	var vis int32 = 0
	var by int32 = 0
	var src int32 = 0
	var cnt int32 = 0
	var rgb int32 = 0
	var cls int32 = 0
	for pos < n {
		line += 1
		e = vtNl(rows, pos)
		if (pos < e) && (port.BlobU8(rows, pos) != 35) {
			kind = port.BlobU8(rows, pos)
			checked += 1
			if kind == 70 {
				status = vtRun(port.SrcOfBlob(port.TestFileSpan(rows, pos+2, e)), ar, dc, a, b, st, cx, ox, cs, out, f0, f1, f2, f3, gl, et, mk, fnt, pg, wd, ln, pa, im, pts, gx)
				port.AssertEqAt(emonT, status, 0, "the file ran", line)
				port.AssertEqAt(emonT, evidence.EvCheck(epages, views, pts, refs, et, feats, gl, wd, ln, mk, fnt, pa, im, oruns, oblocks, olines, owords, osyms, oalts, inks, components, rules, prims, tlines), 0, "the evidence is well formed", line)
				vtWords(emonT, gl, wd, line)
				g = 0
				ii = 0
			}
			if kind == 71 {
				// G vis vby src ncp text
				p = pos + 2
				q = vtTab(rows, p, e)
				vis = vtDec(rows, p, q)
				p = q + 1
				q = vtTab(rows, p, e)
				by = vtDec(rows, p, q)
				p = q + 1
				q = vtTab(rows, p, e)
				src = vtDec(rows, p, q)
				p = q + 1
				q = vtTab(rows, p, e)
				cnt = vtDec(rows, p, q)
				vtGlyphs(emonT, gl, wd, mk, g, cnt, vis, by, src, 0, 0, 0, line)
				gprev = g
				nprev = cnt
				g += cnt
			}
			if kind == 67 {
				// C rgb cls vis ncp text
				p = pos + 2
				q = vtTab(rows, p, e)
				rgb = vtRgb(rows, p, q)
				p = q + 1
				q = vtTab(rows, p, e)
				cls = vtDec(rows, p, q)
				p = q + 1
				q = vtTab(rows, p, e)
				vis = vtDec(rows, p, q)
				p = q + 1
				q = vtTab(rows, p, e)
				cnt = vtDec(rows, p, q)
				vtGlyphs(emonT, gl, wd, mk, g, cnt, vis, -1, 1, rgb, cls, 1, line)
				gprev = g
				nprev = cnt
				g += cnt
			}
			if kind == 79 {
				// O ocgdef ncp
				p = pos + 2
				q = vtTab(rows, p, e)
				vis = vtDec(rows, p, q)
				vtOcg(emonT, gl, mk, gprev, nprev, vis, line)
			}
			if kind == 73 {
				// I vis vby
				p = pos + 2
				q = vtTab(rows, p, e)
				vis = vtDec(rows, p, q)
				by = vtDec(rows, q+1, e)
				port.AssertThatAt(emonT, ii < evidence.ImCount(im), "there is an image row", line)
				if ii < evidence.ImCount(im) {
					port.AssertEqAt(emonT, evidence.ImGet(im, ii, evidence.MfVis()), vis, "image vis", line)
					port.AssertEqAt(emonT, evidence.ImGet(im, ii, evidence.MfVby()), by, "image vby", line)
				}
				ii += 1
			}
			if kind == 78 {
				// N glyphs images
				p = pos + 2
				q = vtTab(rows, p, e)
				port.AssertEqAt(emonT, evidence.GlCount(gl), vtDec(rows, p, q), "glyph count", line)
				port.AssertEqAt(emonT, evidence.ImCount(im), vtDec(rows, q+1, e), "image count", line)
			}
		}
		pos = e + 1
	}
	return checked
}

func TestEveryVisibilityFixtureIsClassifiedAsWritten(emonT *testing.T) {
	// The files of test/vis: white on white and the same colour as the background, clipped, off the page, tiny, painted
	// over, optional content, alpha, hidden OCR layers and a page as a crawler is fed it, and the colour spaces.
	port.AssertThat(emonT, vtRows(emonT, port.TestFile("vis/rows.txt")) > 150, "the rows were read")
}
